using System.Text.Json;
using ArkServerManager.Core;
namespace ArkServerManager.Core.Tests;
public sealed class ClusterTransferSettingsTests
{
    [Fact] public void SixDocumentedKeysAndDownloadMasterSwitchPreserveUnknownEntries()
    {
        const string original=";keep\n[ServerSettings]\nnoTributeDownloads=True\nCustom=untouched\nPreventUploadDinos=True\n[Other]\nPreventDownloadItems=do-not-touch\n";
        var changed=ClusterTransferSettings.Apply(original,[true,false,true],[false,true,false]);var ini=new IniDocument(changed);
        Assert.Equal("False",Assert.Single(ini.GetValues("ServerSettings","PreventUploadSurvivors")));Assert.Equal("True",Assert.Single(ini.GetValues("ServerSettings","PreventUploadDinos")));Assert.Equal("False",Assert.Single(ini.GetValues("ServerSettings","PreventDownloadDinos")));Assert.Equal("False",Assert.Single(ini.GetValues("ServerSettings","noTributeDownloads")));Assert.Equal("untouched",Assert.Single(ini.GetValues("ServerSettings","Custom")));Assert.Equal("do-not-touch",Assert.Single(ini.GetValues("Other","PreventDownloadItems")));Assert.Contains(";keep",changed);Assert.Equal(new[]{false,true,false},ClusterTransferSettings.Read(changed,false));Assert.Equal(new[]{false,true,false},ClusterTransferSettings.Effective([false,false,false],[ClusterTransferOverride.Inherit,ClusterTransferOverride.Allow,ClusterTransferOverride.Block]));
    }
    [Fact] public void RejectsIncompleteAndUnknownTransferRules(){Assert.Throws<ArgumentException>(()=>ClusterTransferSettings.Apply("",[true],[true,true,true]));Assert.Throws<ArgumentException>(()=>ClusterTransferSettings.Effective([true,true,true],[ClusterTransferOverride.Inherit,(ClusterTransferOverride)99,ClusterTransferOverride.Allow]));}
    [Theory][InlineData(false)][InlineData(true)] public async Task SaveAppliesStoppedFilesAndQueuesRunningFilesWithoutChangingThem(bool running)
    {
        var root=Path.Combine(Path.GetTempPath(),"ark-transfer-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        try{
            var repository=new CatalogRepository(Path.Combine(root,"catalog.json"));var cluster=new ClusterDefinition(Guid.NewGuid(),"Fixture cluster",ArkEdition.ASE,new(){Name="Fixture cluster",MaxPlayers=5});var server=new ServerDefinition(Guid.NewGuid(),ArkEdition.ASE,"TheIsland",Path.Combine(root,"server"),new(){Name="Fixture",GamePort=7777,QueryPort=27015,RconPort=32330,MaxPlayers=5},cluster.Id);await repository.ChangeAsync(c=>{c.AddCluster(cluster);c.AddServer(server);});
            var binary=Path.Combine(server.Directory,"ShooterGame","Binaries",OperatingSystem.IsWindows()?"Win64":"Linux",OperatingSystem.IsWindows()?"ShooterGameServer.exe":"ShooterGameServer");Directory.CreateDirectory(Path.GetDirectoryName(binary)!);await File.WriteAllTextAsync(binary,"never launched");var user=Path.Combine(server.Directory,"ShooterGame","Saved","Config",OperatingSystem.IsWindows()?"WindowsServer":"LinuxServer","GameUserSettings.ini");Directory.CreateDirectory(Path.GetDirectoryName(user)!);const string original=";preserve\n[ServerSettings]\nMaxPlayers=5\nCustom=keep\n";await File.WriteAllTextAsync(user,original);
            var stoppedChecks=0;var queue=new PendingConfigurationEdits(repository,Path.Combine(root,"pending.json"),(_,_)=>{stoppedChecks++;return Task.CompletedTask;});await using var operations=new BackgroundOperations(10,1);var service=new ClusterTransferSettingsOperations(repository,root,operations,queue,(action,ct)=>action([new(server.Id,running?ServerState.Running:ServerState.Stopped,true,null){Managed=true}],ct),(_,_)=>Task.CompletedTask);var expected=await service.ReadAsync(cluster.Id);var desired=ClusterTransferSettings.Clone(expected.Rules);desired.Uploads[0]=false;desired.Maps[0].Downloads[1]=ClusterTransferOverride.Block;
            var job=service.Start(new ManagerRequest(1,Guid.NewGuid(),"cluster-transfers-save-start",JsonSerializer.SerializeToElement(new ClusterTransferSave(expected,desired))));for(var i=0;i<100&&job.State is BackgroundOperationState.Queued or BackgroundOperationState.Running;i++){await Task.Delay(30);job=operations.Find(job.Id)!;}Assert.True(job.State==BackgroundOperationState.Succeeded,job.Error);var result=job.Result!.Value.Deserialize<ClusterTransferSaveResult>()!;Assert.Equal(running?1:0,result.Queued);Assert.Equal(running?0:1,result.Applied);Assert.True(running?stoppedChecks==0:stoppedChecks>=1);
            if(running){Assert.Equal(original,await File.ReadAllTextAsync(user));Assert.Single(await queue.ReadAsync(server.Id));}else{var text=await File.ReadAllTextAsync(user);Assert.Contains("Custom=keep",text);Assert.Contains("PreventUploadSurvivors=True",text);Assert.Contains("PreventDownloadDinos=True",text);}
            var reloaded=await service.ReadAsync(cluster.Id);Assert.False(reloaded.Rules.Uploads[0]);Assert.Equal(ClusterTransferOverride.Block,reloaded.Rules.Maps[0].Downloads[1]);Assert.Contains("PreventUploadSurvivors=True",(await repository.ReadAsync()).Clusters.Single().Defaults!.UserSettings!);
        }finally{var resolved=Path.GetFullPath(root);Assert.StartsWith(Path.Combine(Path.GetTempPath(),"ark-transfer-tests-"),resolved);if(Directory.Exists(resolved))Directory.Delete(resolved,true);}
    }
}
